import { RESTPostAPIEmbed, APIEmbed, APIMessageReference, APIAllowedMentions } from '@fluxerjs/types';
export { RESTPostAPIEmbed } from '@fluxerjs/types';

/** Options for attachment builder. */
interface AttachmentPayloadOptions {
    /** Filename (required, will be prefixed with `SPOILER_` if spoiler is true). */
    name: string;
    /** Alt text / description for accessibility (optional). */
    description?: string;
    /** Whether this attachment should be hidden until clicked (optional). */
    spoiler?: boolean;
}
/** API-ready attachment payload. */
interface APIAttachmentPayload {
    /** Attachment ID (index in files array). */
    id: number;
    /** Filename (may be prefixed with `SPOILER_`). */
    filename: string;
    /** Alt text / description (optional). */
    description?: string | null;
}
/**
 * Attachment metadata for message payloads (file bytes sent separately).
 * @example
 * ```ts
 * const attachment = new AttachmentBuilder(0, 'cat.png')
 *   .setDescription('Cute cat')
 *   .setSpoiler();
 * await message.reply({ files: [fileData], attachments: [attachment] });
 * ```
 */
declare class AttachmentBuilder {
    /** Attachment ID (index in files array). */
    readonly id: number;
    /** Filename (may be prefixed with `SPOILER_` if spoiler is true). */
    filename: string;
    /** Alt text / description for accessibility. */
    description?: string | null;
    /** Whether this attachment should be hidden until clicked. */
    spoiler: boolean;
    constructor(id: number, filename: string, options?: Partial<AttachmentPayloadOptions>);
    /**
     * Set attachment filename (preserves spoiler prefix if enabled).
     * @param name - New filename
     * @returns This builder for chaining
     * @throws {@link FluxerError} If filename is empty
     */
    setName(name: string): this;
    /**
     * Set attachment description (alt text for accessibility). Pass null to clear.
     * @param description - Description text or null
     * @returns This builder for chaining
     */
    setDescription(description: string | null): this;
    /**
     * Toggle spoiler flag (adds/removes `SPOILER_` prefix from filename).
     * @param spoiler - Whether this attachment should be hidden
     * @returns This builder for chaining
     */
    setSpoiler(spoiler?: boolean): this;
    /**
     * Serialize to API attachment payload.
     * @returns API-ready attachment metadata
     */
    toJSON(): APIAttachmentPayload;
}

/** Options for embed media (image/thumbnail). */
interface EmbedMediaOptions {
    /** Media URL (HTTP(S) or `attachment://filename`). */
    url: string;
    /** Alt text for accessibility (optional). */
    description?: string | null;
}
/** Options for embed author. */
interface EmbedAuthorOptions {
    /** Author name (max 256 characters, auto-truncated). */
    name: string;
    /** Author icon URL (optional). */
    iconURL?: string;
    /** Author URL (clickable name) (optional). */
    url?: string;
}
/** Options for embed footer. */
interface EmbedFooterOptions {
    /** Footer text (max 2048 characters, auto-truncated). */
    text: string;
    /** Footer icon URL (optional). */
    iconURL?: string;
}
/** Embed field data (name-value pair). */
interface EmbedFieldData {
    /** Field name (max 256 characters, auto-truncated). */
    name: string;
    /** Field value (max 1024 characters, auto-truncated). */
    value: string;
    /** Whether this field should display inline. */
    inline?: boolean;
}
/**
 * Request-only embed builder. Emits {@link RESTPostAPIEmbed} (no video/audio).
 * @example
 * ```ts
 * const embed = new EmbedBuilder()
 *   .setTitle('Hello')
 *   .setDescription('World')
 *   .setColor('#5865F2')
 *   .setTimestamp();
 * await channel.send({ embeds: [embed] });
 * ```
 */
declare class EmbedBuilder {
    /** Partial embed data (built incrementally via setters). */
    readonly data: Partial<RESTPostAPIEmbed>;
    /**
     * Set embed title (max 256 characters). Pass null to clear.
     * @param title - Title text or null
     * @returns This builder for chaining
     * @throws {RangeError} If title exceeds 256 characters
     */
    setTitle(title: string | null): this;
    /**
     * Set embed description (max 4096 characters). Pass null to clear.
     * @param description - Description text or null
     * @returns This builder for chaining
     * @throws {RangeError} If description exceeds 4096 characters
     */
    setDescription(description: string | null): this;
    /**
     * Set embed URL (title becomes clickable). Pass null to clear.
     * @param url - HTTP(S) URL or null
     * @returns This builder for chaining
     * @throws {@link FluxerError} If URL is invalid
     */
    setURL(url: string | null): this;
    /**
     * Set embed color. Pass null to clear.
     * @param color - Number (24-bit RGB), hex string (`#5865F2`), or RGB tuple, or null
     * @returns This builder for chaining
     */
    setColor(color: number | string | [number, number, number] | null): this;
    /**
     * Set embed timestamp. Pass null to clear.
     * @param timestamp - Date object, Unix ms, or undefined (defaults to now), or null
     * @returns This builder for chaining
     */
    setTimestamp(timestamp?: Date | number | null): this;
    /**
     * Set embed author. Pass null to clear.
     * @param options - Author name, icon URL, and URL, or null
     * @returns This builder for chaining
     */
    setAuthor(options: EmbedAuthorOptions | null): this;
    /**
     * Set embed footer. Pass null to clear.
     * @param options - Footer text and optional icon URL, or null
     * @returns This builder for chaining
     */
    setFooter(options: EmbedFooterOptions | null): this;
    /**
     * Set embed image (large media below description). Pass null to clear.
     * @param input - URL string or media options, or null
     * @returns This builder for chaining
     * @throws {@link FluxerError} If URL is invalid
     */
    setImage(input: string | EmbedMediaOptions | null): this;
    /**
     * Set embed thumbnail (small media in top-right corner). Pass null to clear.
     * @param input - URL string or media options, or null
     * @returns This builder for chaining
     * @throws {@link FluxerError} If URL is invalid
     */
    setThumbnail(input: string | EmbedMediaOptions | null): this;
    /**
     * Replace all fields (max 25). Pass empty array to clear.
     * @param fields - Field objects (name, value, inline)
     * @returns This builder for chaining
     */
    setFields(...fields: EmbedFieldData[]): this;
    /**
     * Add fields (up to 25 total). Existing fields are preserved.
     * @param fields - Field objects to append
     * @returns This builder for chaining
     */
    addFields(...fields: EmbedFieldData[]): this;
    /**
     * Splice fields (like Array.prototype.splice).
     * @param index - Start index
     * @param deleteCount - Number of fields to remove
     * @param fields - Fields to insert at index
     * @returns This builder for chaining
     */
    spliceFields(index: number, deleteCount: number, ...fields: EmbedFieldData[]): this;
    /**
     * Wire payload: request keys only, snake_case nested media/author/footer.
     * @returns API-ready embed object
     * @throws {RangeError} If total character count exceeds 6000
     */
    toJSON(): RESTPostAPIEmbed;
    /**
     * Copy request fields only — response video/audio/type/provider are ignored.
     * @param data - API embed from message or webhook
     * @returns New builder instance with copied data
     */
    static from(data: APIEmbed | RESTPostAPIEmbed): EmbedBuilder;
}

interface MessagePayloadData {
    content?: string | null;
    embeds?: RESTPostAPIEmbed[] | null;
    attachments?: Array<{
        id: number;
        filename: string;
        description?: string | null;
    }>;
    message_reference?: APIMessageReference | null;
    allowed_mentions?: APIAllowedMentions | null;
    tts?: boolean;
    flags?: number;
}
type MessagePayloadCreateOptions = Omit<MessagePayloadData, 'embeds'> & {
    embeds?: (RESTPostAPIEmbed | EmbedBuilder)[] | null;
};
type AttachmentInput = AttachmentBuilder | {
    id: number;
    filename: string;
    description?: string | null;
};
type ReplyInput = {
    channelId: string;
    messageId: string;
    guildId?: string | null;
} | {
    channel_id: string;
    message_id: string;
    guild_id?: string | null;
} | APIMessageReference;
/**
 * Fluent message builder (camelCase setters → snake_case via {@link toJSON}).
 *
 * Prefer passing the builder to `channel.send(payload)` / `prepareMessagePostPayload(payload)`
 * in `@fluxerjs/core` so defaults (allowed mentions, reply ping) apply. Use {@link toJSON}
 * only for low-level REST bodies.
 *
 * @example
 * ```ts
 * const payload = new MessagePayload()
 *   .setContent('Hello!')
 *   .addEmbed(new EmbedBuilder().setTitle('Title'));
 * await channel.send(payload);
 * ```
 */
declare class MessagePayload {
    /** Max content length (2000 characters). */
    static readonly ContentMaxLength = 2000;
    /** Partial message data (built incrementally via setters). */
    readonly data: MessagePayloadData;
    /**
     * Set message content (max 2000 characters). Pass null to clear.
     * @param content - Text content or null
     * @returns This builder for chaining
     * @throws {RangeError} If content exceeds 2000 characters
     */
    setContent(content: string | null): this;
    /**
     * Replace all embeds (max 10). Pass null or empty array to clear.
     * @param embeds - Array of embed objects or {@link EmbedBuilder} instances, or null
     * @returns This builder for chaining
     * @throws {RangeError} If embeds array exceeds 10
     */
    setEmbeds(embeds: (RESTPostAPIEmbed | EmbedBuilder)[] | null): this;
    /**
     * Add an embed (up to 10 total). Existing embeds are preserved.
     * @param embed - Embed object or {@link EmbedBuilder}
     * @returns This builder for chaining
     * @throws {RangeError} If adding would exceed 10 embeds
     */
    addEmbed(embed: RESTPostAPIEmbed | EmbedBuilder): this;
    /**
     * Set attachments metadata (file bytes sent separately via multipart). Pass null to clear.
     * @param attachments - Array of {@link AttachmentBuilder} or attachment metadata, or null
     * @returns This builder for chaining
     */
    setAttachments(attachments: AttachmentInput[] | null): this;
    /**
     * Set message reference (reply target). Pass null to clear.
     * @param reference - Reply target (channel/message IDs), or null
     * @returns This builder for chaining
     */
    setReply(reference: ReplyInput | null): this;
    /**
     * Set allowed mentions (controls who can be pinged). Pass null to clear.
     * @param allowedMentions - Allowed mention rules, or null
     * @returns This builder for chaining
     */
    setAllowedMentions(allowedMentions: APIAllowedMentions | null): this;
    /**
     * Set text-to-speech flag.
     * @param tts - Whether to use TTS
     * @returns This builder for chaining
     */
    setTTS(tts: boolean): this;
    /**
     * Set message flags (e.g., suppress embeds).
     * @param flags - Message flags bitfield
     * @returns This builder for chaining
     */
    setFlags(flags: number): this;
    /**
     * Serialize to API payload (snake_case keys).
     * @returns API-ready message data
     */
    toJSON(): MessagePayloadData;
    /**
     * Create from string content or options object.
     * @param contentOrOptions - Text content or full payload options
     * @returns New MessagePayload instance
     */
    static create(contentOrOptions?: string | MessagePayloadCreateOptions): MessagePayload;
}

export { type APIAttachmentPayload, AttachmentBuilder, type AttachmentPayloadOptions, type EmbedAuthorOptions, EmbedBuilder, type EmbedFieldData, type EmbedFooterOptions, type EmbedMediaOptions, MessagePayload, type MessagePayloadCreateOptions, type MessagePayloadData };
